public final class WashingMachine {
    private State state = State.ENABLED;          // guarded by this

    public synchronized boolean start() {
        if (state != State.ENABLED) return false; // balk, no side effects
        state = State.WASHING;                    // check and act, one monitor
        return true;
    }

    public synchronized void endOfWashing() { state = State.ENABLED; }
}

