private final ReentrantLock gate = new ReentrantLock();
private State state = State.IDLE;        // guarded by gate
boolean tryStart() {
    if (!gate.tryLock()) return false;       // balk instead of queueing
    try {
        if (state != State.IDLE) return false;   // second, state-level balk
        state = State.RUNNING;
        return true;
    } finally {
        gate.unlock();                       // always released
    }
}
